mapper.select:
SELECT i.id as institutionId, i.institution_no as institutionNo, i.institution_name as institutionName, i.region as region, c.id as contractId, c.contract_no as contractNo, c.contract_amount as contractAmount, c.sign_date as signDate, c.expire_date as expireDate, c.responsible_person as responsiblePerson, c.contract_status as contractStatus, c.remark as remark FROM institution i LEFT JOIN ( SELECT c2.*, ROW_NUMBER() OVER(PARTITION BY c2.institution_no ORDER BY CASE c2.contract_status WHEN 'ACTIVE' THEN 1 WHEN 'PENDING' THEN 2 ELSE 3 END, CASE c2.contract_status WHEN 'PENDING' THEN ABS(DATEDIFF(c2.sign_date, CURDATE())) WHEN 'INACTIVE' THEN ABS(DATEDIFF(c2.expire_date, CURDATE())) ELSE 0 END ) as rn FROM contract c2
WHERE YEAR(c2.sign_date) = #{year}
) c ON i.institution_no = c.institution_no AND c.rn = 1 WHERE i.institution_status = 'NORMAL'
AND i.institution_no = #{institutionNo}
AND i.region = #{region}
AND ( i.institution_no LIKE CONCAT('%', #{keyword}, '%') OR i.institution_name LIKE CONCAT('%', #{keyword}, '%') OR c.contract_no LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY i.institution_no LIMIT #{offset}, #{size}

SELECT COUNT(DISTINCT i.id) FROM institution i
WHERE i.institution_status = 'NORMAL'

    AND EXISTS (
        SELECT 1 FROM contract c 
        WHERE c.institution_no = i.institution_no 
        AND YEAR(c.sign_date) = #{year}
    )


    AND i.institution_no = #{institutionNo}


    AND i.region = #{region}


    AND (
        i.institution_no LIKE CONCAT('%', #{keyword}, '%')
        OR i.institution_name LIKE CONCAT('%', #{keyword}, '%')
        OR EXISTS (
            SELECT 1 FROM contract c 
            WHERE c.institution_no = i.institution_no 
            AND c.contract_no LIKE CONCAT('%', #{keyword}, '%')
        )
    )

mapper.update:
UPDATE contract
contract_no = #{contractNo}, institution_no = #{institutionNo}, contract_amount = #{contractAmount}, sign_date = #{signDate}, expire_date = #{expireDate}, responsible_person = #{responsiblePerson}, contract_status = #{contractStatus}, remark = #{remark},
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM contract 
WHERE YEAR(sign_date) = #{year} 
   OR YEAR(expire_date) = #{year}
   OR (sign_date < CONCAT(#{year}, '-01-01') AND expire_date > CONCAT(#{year}, '-12-31'))

SELECT COALESCE(SUM(contract_amount), 0) FROM contract 
WHERE YEAR(sign_date) = #{year} 
   OR YEAR(expire_date) = #{year}
   OR (sign_date < CONCAT(#{year}, '-01-01') AND expire_date > CONCAT(#{year}, '-12-31'))

SELECT * FROM contract 
WHERE institution_no = #{institutionNo}

    AND id != #{excludeId}

SELECT COUNT(*) FROM contract c
INNER JOIN institution i ON c.institution_no = i.institution_no
WHERE i.region = #{region}
   AND (
       YEAR(c.sign_date) = #{year} 
       OR YEAR(c.expire_date) = #{year}
       OR (c.sign_date < CONCAT(#{year}, '-01-01') AND c.expire_date > CONCAT(#{year}, '-12-31'))
   )

SELECT COALESCE(SUM(c.contract_amount), 0) FROM contract c
INNER JOIN institution i ON c.institution_no = i.institution_no
WHERE i.region = #{region}
   AND (
       YEAR(c.sign_date) = #{year} 
       OR YEAR(c.expire_date) = #{year}
       OR (c.sign_date < CONCAT(#{year}, '-01-01') AND c.expire_date > CONCAT(#{year}, '-12-31'))
   )
